void bubble_sort(int a[], int n)
{
    int swapHappenedInThisPass;
    int currentIndex;
    int temporaryStorageForSwapping;
    int numberOfElementsToSort = n;

    swapHappenedInThisPass = 1;
    while (swapHappenedInThisPass == 1)
    {
        swapHappenedInThisPass = 0;
        currentIndex = 0;
        while (currentIndex < numberOfElementsToSort - 1)
        {
            if (a[currentIndex] > a[currentIndex + 1])
            {
                temporaryStorageForSwapping = a[currentIndex];
                a[currentIndex] = a[currentIndex + 1];
                a[currentIndex + 1] = temporaryStorageForSwapping;
                swapHappenedInThisPass = 1;
            }
            else
            {
                swapHappenedInThisPass = swapHappenedInThisPass;
            }
            currentIndex = currentIndex + 1;
        }
        numberOfElementsToSort = numberOfElementsToSort - 1;
    }
}

