int factorial(int n)
{
    int totalValueSoFar = 1;
    int loopCounter = 1;
    int checkFlag = 0;
    if(n == 0)
    {
        totalValueSoFar = 1;
        checkFlag = 1;
    }
    else
    {
        while(loopCounter <= n)
        {
            totalValueSoFar = totalValueSoFar * loopCounter;
            loopCounter = loopCounter + 1;
        }
        checkFlag = 1;
    }
    if(checkFlag == 1)
    {
        return totalValueSoFar;
    }
    else
    {
        return totalValueSoFar;
    }
    return totalValueSoFar;
}

int total_energy(int cells[], int n)
{
    int sum = 0;
    int i;
    // sum zero pasun suru kara
    for(i = 0; i < n; i = i + 1)
    {
        sum = sum + *(cells + i); // pratyek cell chi value add kara
    }
    // final sum return kara
    return sum;
}
